import{_ as a,o,a as t,b as i}from"./app.DKoEZOcr.js";const r="/ascendc.github.io/pr/5487/assets/matrix_computation_workflow_tensor_api.CVD2kivc.png",n=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"矩阵计算","link":"/api/SIMD-API/tensor_api/matrix_compute/matrix_compute"},{"text":"概述","link":"/api/SIMD-API/tensor_api/matrix_compute/overview"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/matrix_compute/overview.md","filePath":"api/SIMD-API/tensor_api/matrix_compute/overview.md","outlineHeaders":[{"level":2,"title":"矩阵计算单元","slug":"矩阵计算单元","link":"#矩阵计算单元"},{"level":2,"title":"矩阵计算流程","slug":"矩阵计算流程","link":"#矩阵计算流程"}],"lastUpdated":1787967772000}'),p={name:"api/SIMD-API/tensor_api/matrix_compute/overview.md"};function c(_,e,l,s,m,u){return o(),t("div",null,[...e[0]||(e[0]=[i('<div><article class="markdown-body"><h1>概述</h1><h2 id="矩阵计算单元">矩阵计算单元<a class="header-anchor" href="#矩阵计算单元">​</a></h2><p>矩阵计算单元的详细描述请参考<a href="../../basic_api/cube_compute_ISASI/overview/cube_compute_unit.html">LINK</a>。</p><h2 id="矩阵计算流程">矩阵计算流程<a class="header-anchor" href="#矩阵计算流程">​</a></h2><p>Tensor API针对矩阵计算编程模型提供了两类接口，分别承载Cube核中各个通路的搬运能力和计算能力，如下图所示：</p><p><strong>图1</strong> 普通矩阵基础计算流程图<span id="zh-cn_topic_0000002535567224_fig135639216483"></span></p><p><img src="'+r+'" alt="普通矩阵基础计算流程图"></p><ol><li><p>通过<code>copy</code>接口将A、B原始矩阵的Global Memory数据搬运到L1 Buffer中（如果存在Bias/随路量化，则同样通过<code>copy</code>搬运到L1 Buffer中）。详细内容请参考<a href="cube_compute_load/cube_compute_load.html">矩阵计算的搬入</a>。</p></li><li><p>通过<code>copy</code>接口将A、B矩阵分别加载到L0A Buffer和L0B Buffer上准备计算（如果存在Bias/随路量化，则通过<code>copy</code>将L1 Buffer中的Bias数据/量化系数数据搬运到BiasTable Buffer/Fixpipe Buffer上）。详细内容请参考<a href="cube_compute_load/cube_compute_load.html">矩阵计算的搬入</a>。</p></li><li><p>通过<code>mmad</code>接口对L0A Buffer、L0B Buffer、BiasTable Buffer上面的数据进行矩阵计算，并输出结果到L0C Buffer上。详细内容请参考<a href="mmad_compute/mmad_compute.html">mmad计算</a>。</p></li><li><p>通过<code>copy</code>接口将L0C Buffer的数据进行处理并搬出到Global Memory，<code>copy</code>接口可以利用Fixpipe Buffer数据进行如随路量化、Relu等操作。详细内容请参考<a href="cube_compute_store/cube_compute_store.html">矩阵计算的搬出</a>。</p></li></ol></article></div>',1)])])}const f=a(p,[["render",c]]);export{n as __pageData,f as default};
